import * as React from "react";
import { serverLogger } from "../../../utils/index.js";
import { renderToStringAdapter } from "../../../react/index.js";
import { getComponentId, isClientComponent, registerClientRef, } from "./component-detector.js";
import { escapeHtml, renderAttributes, treeToHTML } from "./html-generator.js";
import { serializeProps } from "./prop-serializer.js";
const logger = serverLogger.component("rsc");
/** Recursively renders a component tree to RSC nodes */
export async function renderTree(Component, props, clientManifest, clientRefs, reactVersion, reactRuntime) {
    const runtimeReact = reactRuntime?.react ?? React;
    if (Component == null || typeof Component === "string" || typeof Component === "number") {
        return { type: "html", html: Component == null ? "" : escapeHtml(String(Component)) };
    }
    if (runtimeReact.isValidElement(Component)) {
        return processElement(Component, clientManifest, clientRefs, reactVersion, reactRuntime);
    }
    if (typeof Component !== "function") {
        return { type: "html", html: escapeHtml(String(Component)) };
    }
    const rscComponent = Component;
    if (isClientComponent(rscComponent, clientManifest)) {
        const componentId = getComponentId(rscComponent);
        registerClientRef(componentId, rscComponent, clientManifest, clientRefs);
        return {
            type: "client",
            component: componentId,
            props: serializeProps(props),
            children: await renderBoundaryChildren(props.children, clientManifest, clientRefs, reactVersion, reactRuntime),
        };
    }
    try {
        const element = Component.prototype?.render
            ? runtimeReact.createElement(Component, props)
            : await Component(props);
        if (!element)
            return { type: "html", html: "" };
        if (runtimeReact.isValidElement(element)) {
            return processElement(element, clientManifest, clientRefs, reactVersion, reactRuntime);
        }
        return { type: "html", html: escapeHtml(String(element)) };
    }
    catch (error) {
        logger.error("Error rendering component:", error);
        throw error;
    }
}
/** Processes a React element into RSC node representation */
export async function processElement(element, clientManifest, clientRefs, reactVersion, reactRuntime) {
    const runtimeReact = reactRuntime?.react ?? React;
    const { type } = element;
    // Cast props for React 19 compatibility (props is unknown in R19 types)
    const props = element.props;
    if (type === runtimeReact.Fragment) {
        const children = await renderChildren(props.children, clientManifest, clientRefs, reactVersion, reactRuntime);
        return { type: "fragment", children };
    }
    if (typeof type === "string") {
        const processedChildren = await renderChildren(props.children, clientManifest, clientRefs, reactVersion, reactRuntime);
        if (processedChildren.every((child) => child.type === "html")) {
            const html = await renderToStringAdapter(element, { reactVersion, reactRuntime });
            return { type: "html", html };
        }
        const attrs = renderAttributes(props, type);
        const childrenHtml = await Promise.all(processedChildren.map((child) => treeToHTML(child, clientRefs, clientManifest)));
        const html = `<${type}${attrs}>${childrenHtml.join("")}</${type}>`;
        return { type: "html", html };
    }
    if (typeof type === "function") {
        return renderTree(type, props, clientManifest, clientRefs, reactVersion, reactRuntime);
    }
    const html = await renderToStringAdapter(element, { reactVersion, reactRuntime });
    return { type: "html", html };
}
export function renderChildren(children, clientManifest, clientRefs, reactVersion, reactRuntime) {
    const runtimeReact = reactRuntime?.react ?? React;
    if (!children)
        return Promise.resolve([]);
    return Promise.all(runtimeReact.Children.toArray(children).map((child) => {
        if (runtimeReact.isValidElement(child)) {
            return processElement(child, clientManifest, clientRefs, reactVersion, reactRuntime);
        }
        return Promise.resolve({ type: "html", html: escapeHtml(String(child)) });
    }));
}
async function renderBoundaryChildren(children, clientManifest, clientRefs, reactVersion, reactRuntime) {
    const runtimeReact = reactRuntime?.react ?? React;
    return await Promise.all(runtimeReact.Children.toArray(children).map((child) => renderBoundaryChild(child, clientManifest, clientRefs, reactVersion, reactRuntime)));
}
async function renderBoundaryChild(child, clientManifest, clientRefs, reactVersion, reactRuntime) {
    const runtimeReact = reactRuntime?.react ?? React;
    if (typeof child === "string" || typeof child === "number") {
        return { type: "html", text: String(child) };
    }
    if (!runtimeReact.isValidElement(child)) {
        return { type: "fragment", children: [] };
    }
    const type = child.type;
    const props = child.props;
    if (type === runtimeReact.Fragment) {
        return {
            type: "fragment",
            children: await renderBoundaryChildren(props.children, clientManifest, clientRefs, reactVersion, reactRuntime),
        };
    }
    if (typeof type === "string") {
        return {
            type: "server",
            component: type,
            props: serializeProps(props),
            children: await renderBoundaryChildren(props.children, clientManifest, clientRefs, reactVersion, reactRuntime),
        };
    }
    if (typeof type === "function") {
        const Component = type;
        if (isClientComponent(Component, clientManifest)) {
            const componentId = getComponentId(Component);
            registerClientRef(componentId, Component, clientManifest, clientRefs);
            return {
                type: "client",
                component: componentId,
                props: serializeProps(props),
                children: await renderBoundaryChildren(props.children, clientManifest, clientRefs, reactVersion, reactRuntime),
            };
        }
        const rendered = Component.prototype?.render
            ? new Component(props).render()
            : await Component(props);
        const renderedChildren = await renderBoundaryChildren(rendered, clientManifest, clientRefs, reactVersion, reactRuntime);
        return renderedChildren.length === 1
            ? renderedChildren[0]
            : { type: "fragment", children: renderedChildren };
    }
    const html = await renderToStringAdapter(child, { reactVersion, reactRuntime });
    return { type: "html", html };
}
